function brainstorm(topic, opts){
  opts=opts||{}; var n=opts.n!=null?opts.n:12; if(n<1)n=1; else if(n>40)n=40;
  topic=(topic||'产品').trim()||'产品';
  var ANG=['如何','为什么','如果……会怎样','有没有更简单的做法','能否自动化','从用户视角看','从成本视角看','从风险视角看','结合 AI','结合线下场景','结合社交传播','结合数据驱动'];
  var ACT=['优化','重构','拆解','组合','替代方案','外包','最小可行','快速试错','建立标准','设计指标','做减法','做加法'];
  var out=[];
  for(var i=0;i<n;i++){ var a=ANG[i%ANG.length], b=ACT[(i*3)%ACT.length];
    out.push(a+'「'+topic+'」：尝试'+b+'，并记录一个可验证假设。'); }
  return out.join('\n');
}

var EXPORTS={brainstorm:brainstorm};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BrainstormForgePure = EXPORTS; }
